fix:
Collect and sort the keys or elements deterministically before iterating when order is required.
```rust
fn serialize_config(map: &HashMap<String, String>) -> String {
    let mut keys: Vec<_> = map.keys().collect();
    keys.sort(); // Restores deterministic ordering
    let mut out = String::new();
    for k in keys {
        out.push_str(&format!("{}={};", k, map.get(k).unwrap()));
    }
    out
}
```
